    print(f"{a:9s} {r5*100 if r5 else 0:8.2f} {r10*100 if r10 else 0:8.2f} {r20v*100 if r20v else 0:8.2f} {r60*100 if r60 else 0:8.2f} {v*100 if v else 0:7.1f} {str(trend):>9s}")

# cross-sectional dispersion of 20d returns
vals = [v for v in r20.values() if v is not None]
print(f"\nCross-sectional dispersion (20d ret): mean={statistics.mean(vals)*100:.2f}%  stdev={statistics.pstdev(vals)*100:.2f}%  max={max(vals)*100:.2f}%  min={min(vals)*100:.2f}%")

# VIX and DXY
for f in ['VIX','DXY','USDJPY','EURUSD','USDCNY']:
    s = load(f'../persistent/index_data/{f}.csv')
    if s:
        r20v = ret(s,20); r10v = ret(s,10)
        print(f"{f}: last={s[-1][1]:.2f} r10={r10v*100 if r10v else 0:.2f}% r20={r20v*100 if r20v else 0:.2f}%")
