    with open(srcdir+fn) as f:
        for r in csv.reader(f):
            if r[0]=='date': continue
            try: date=dt.date.fromisoformat(r[0])
            except: continue
            if date>CUT or date<dt.date(2031,3,31): continue
            d[date]=float(r[2])  # close
    return d

